if zn==nGd[1966]then
An.speed=1.2
elseif zn==nGd[1967]then
An.fly,An.speed=0.2,1.25
elseif zn==nGd[1968]then
An.ice=0.5
elseif zn==nGd[1969]then
An.range,An.zap=0.7,{every=10,stun=3}
elseif zn==nGd[1970]then
An.kinds.physical,An.kinds.magic=100/250-1,0.25
elseif zn==nGd[1893]then
An.speed,An.noCC=1.5,true
elseif zn==nGd[1971]then
An.speed=1.25
elseif zn==nGd[1972]then
An.kinds.magic,An.kinds.physical,An.shroud=100/175-1,0.25,0.2
elseif zn==nGd[1973]then
An.starfall=kb.starfall()
end
return An
end
function kb.starfall()
local Bn=type(P.hunt)==nGd[1758]and P.hunt.starfall
if type(Bn)~=nGd[1758]or(tonumber(Bn.runs)or 0)<1 or not tonumber(Bn.perWave)then
return nil
end
return Bn
end
kb.STARFALL_PER_WAVE,kb.GOLEM_REMNANTS=0.1,1+0.01*20
function kb.starfallRemnants(Cn)
local Dn=kb.starfall()
local En=Dn and tonumber(Dn.perWave)or kb.STARFALL_PER_WAVE
return math.max(0,En*(tonumber(Cn)or 50)*kb.GOLEM_REMNANTS)
end
function bb.noteStar(Fn,Gn)
bb.stars=bb.stars or setmetatable({},{__mode=nGd[1974]})
if bb.stars[Fn]then
return
end
bb.stars[Fn]=true
local Hn=bb.wave()
bb.starRun=bb.starRun or{n=0,waves={},hpK={}}
local In=bb.starRun
In.n=In.n+1
In.waves[Hn]=(In.waves[Hn]or 0)+1
local Jn=bb.info and bb.info.cfgById and bb.info.cfgById.star_golem_1
local Kn,Ln=pcall(fb.enemy,bb.info,Jn,Hn)
local Mn=Gn and tonumber(Gn.MaxHealth)or 0
if Jn and Kn and Ln and(Ln.hp or 0)>0 and Mn>0 then
table.insert(In.hpK,Mn/Ln.hp)
end
end
function kb.starfallRecord()
local Nn=bb.starRun
if not(Nn and Nn.n>0)then
return
end
local On=math.max(1,bb.wave())
local Pn=Nn.n/On
local Qn
if#Nn.hpK>0 then
local Rn=table.clone(Nn.hpK)
table.sort(Rn)
Qn=Rn[math.floor(#Rn/2)+1]
end
local Sn=type(P.hunt.starfall)==nGd[1758]and P.hunt.starfall or{}
local Tn=(tonumber(Sn.runs)or 0)+1
local Un=1/math.min(Tn,5)
P.hunt.starfall={runs=Tn,perWave=Sn.perWave and(Sn.perWave+(Pn-Sn.perWave)*Un)or Pn,hpK=Qn and(Sn.hpK and(Sn.hpK+(Qn-Sn.hpK)*Un)or Qn)or Sn.hpK,at=os.time()}
local Vn,Wn
for Xn in pairs(Nn.waves)do
Vn=math.min(Vn or Xn,Xn)
Wn=math.max(Wn or Xn,Xn)
end
F.log(1,nGd[1975],string.format(nGd[1976],Nn.n,On,Pn,tostring(Vn),tostring(Wn),Qn or 0))
return{n=Nn.n,waves=On,hpK=Qn and math.floor(Qn*100+0.5)/100 or nil}
end
function kb.perWave(Yn)
