function kb.firstValue(Ao,Bo)
local Co=kb.board()
if not Co then
return 0,{}
end
local Do,Eo=0,{}
local Fo=Ao and table.find(Co.board,Ao)
if Fo and not Co.maps[Ao]then
local Go=0
for Ho,Io in ipairs(Co.core.LINES)do
if table.find(Io.cells,Fo)then
Go=Go+1
end
end
Do=Do+Go*kb.lineGems()/Co.core.SIZE
table.insert(Eo,nGd[1979])
end
if Bo and Bo~=nGd[1980]and not Co.weathers[Bo]then
Do=Do+(1000+5000*O.pearlValue+50*W.remnantGems(nGd[1978]))/kb.WEATHERS
table.insert(Eo,nGd[1981])
end
if not next(Co.maps)then
Do=Do+500+4500*O.pearlValue+200
table.insert(Eo,nGd[1982])
end
return Do,Eo
end
