function kb.charmScore(Lp,Mp)
local Np=(Mp and tonumber(Mp.p))or 0.5
local Op,Pp,Qp=Lp.rolls.unit_damage or 0,Lp.rolls.reward_mul or 0,0
for Rp,Sp in pairs(Lp.rolls)do
if Rp~=nGd[2008]and Rp~=nGd[2009]then
Qp=Qp+Sp
end
end
if Np>=0.92 then
return Pp*3+Op+Qp*0.5
end
return Op*3+Pp+Qp*0.5
end
