return nil
end
P.charm=type(P.charm)==nGd[1758]and P.charm or{}
if os.time()-(tonumber(P.charm.failAt)or 0)<1800 then
return nil
end
local eq,fq
for gq,hq in ipairs(kb.charms())do
local iq=kb.charmScore(hq,dq)
if not fq or iq>fq then
eq,fq=hq,iq
end
end
if not eq then
return nil
end
local jq=kb.charmOn()or(F.where==nGd[1829]and P.charm.uuid)or nil
if jq==eq.uuid then
return nil
end
return eq,jq
end
function kb.charmTick(kq)
local lq,mq=kb.charmWant(kq)
if not lq then
return
end
mq=kb.charmOn()
if mq then
F.request(nGd[2016],nGd[2017],mq)
task.wait(1)
end
F.request(nGd[2016],nGd[2018],lq.uuid)
local nq=U.now()
while U.now()-nq<4 and kb.charmOn()~=lq.uuid do
task.wait(0.5)
end
if kb.charmOn()==lq.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=lq.uuid,os.time(),nil
F.saveSoon()
F.log(1,nGd[2019],string.format(nGd[2020],kb.charmWords(lq),tostring(kq.label),math.floor((tonumber(kq.p)or 0)*100+0.5),(tonumber(kq.p)or 0)>=0.92 and nGd[2011]or nGd[1922]))
else
P.charm.failAt=os.time()
F.saveSoon()
F.log(1,nGd[2019],string.format(nGd[2021],kb.charmWords(lq)))
end
end
function kb.weatherStrength(oq)
local pq=kb.fx(oq)
local qq=pq.dmg/pq.cd/pq.hp/pq.speed*(1+(pq.range-1)/2)
for rq,sq in pairs(pq.kinds)do
qq=qq*(1+bb.rogueShare(rq)*sq)
end
if pq.ice>0 then
local tq=bb.rogueShare(nGd[1893])
qq=qq*(tq+(1-tq)/(1-pq.ice+pq.ice/fb.modFactor(nGd[2022])))
end
if pq.fly>0 then
qq=qq*(1-pq.fly*0.5)
end
if pq.noCC then
qq=qq*0.95
end
if pq.shroud then
qq=qq*0.9
end
if pq.zap then
qq=qq*0.85
end
return qq/kb.weatherK(oq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(uq)
local vq=uq and type(P.hunt)==nGd[1758]and type(P.hunt.wk)==nGd[1758]and P.hunt.wk[tostring(uq)]or nil
return type(vq)==nGd[1758]and tonumber(vq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(nGd[662]):GetPlayers()>1 then
return
end
local wq=bb.huntWeather or kb.weatherNow()
local xq,yq=bb.pred,bb.calRun
if not wq or type(xq)~=nGd[1758]or type(yq)~=nGd[1758]then
return
end
local function zq(Aq,Bq)
return type(Aq)==nGd[1758]and tonumber(Aq[Bq]or Aq[tostring(Bq)])or nil
end
local Cq={}
for Dq=2,bb.wave()do
local Eq,Fq=zq(yq.alive,Dq),zq(xq.aliveAt,Dq)
if Eq and Fq and Eq>0 and Fq>0 then
table.insert(Cq,Eq/Fq)
end
end
if#Cq<3 then
return
end
table.sort(Cq)
local Gq=Cq[math.ceil(#Cq/2)]
P.hunt.wk=type(P.hunt.wk)==nGd[1758]and P.hunt.wk or{}
local Hq=P.hunt.wk[tostring(wq)]
local Iq=math.min(kb.WEATHER_K_RUNS-1,type(Hq)==nGd[1758]and tonumber(Hq.n)or 0)
local Jq=kb.weatherK(wq)
local Kq=math.max(1,Iq)
local Lq=math.exp((Kq*math.log(Jq)+math.log(Jq*Gq))/(Kq+1))
Lq=U.clamp(Lq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(wq),old=Hq}
P.hunt.wk[tostring(wq)]={k=Lq,n=(type(Hq)==nGd[1758]and tonumber(Hq.n)or 0)+1,at=os.time()}
F.log(1,nGd[2023],string.format(nGd[2024],tostring(wq),Gq,tostring(wq),Lq,Jq,P.hunt.wk[tostring(wq)].n))
end
