local YK,ZK=pcall(N.LU.Infinite.infinite_get_normal_unit_chance,XK,RK)
ZK=YK and tonumber(ZK)or 0
UK=UK+ZK
if OK(WK)then
VK=VK+ZK
end
end
end
if UK>0 then
HK=HK+(SK and tonumber(TK)or 10)*VK/UK
end
else
local _K=JK.list[RK]
for aL,bL in ipairs(U.list(_K and _K.wave))do
if OK(bL.unit)then
HK=HK+(tonumber(bL.amount)or 1)
end
end
end
end
HK=math.floor(HK+0.5)
end)
W._spawns[FK]={n=HK,at=os.time()}
