function jb.gainXp(OQ,PQ)
local QQ,RQ=tonumber(OQ.xp)or 0,jb.xpFor(OQ.unit_id,jb.cap(OQ))
local SQ=math.max(0,RQ-QQ)
if SQ<=0 or(PQ or 0)<=0 then
return 0,0
end
local TQ=math.min(PQ,SQ)
local UQ=jb.base(OQ)
if UQ<=0 then
return 0,TQ
end
return jb.share(OQ.unit_id)*(jb.score(jb.whatIf(OQ,{xp=QQ+TQ}))/UQ-1)*100,TQ
end
