function jb.relicWorth(VQ,WQ)
local XQ=WQ._unique_item_data and WQ._unique_item_data._unique_relic_data
if not XQ then
return 0
end
local YQ=N.Items[WQ.item_id]or{}
local ZQ,_Q=V.types(VQ.unit_id)
if YQ.main_damage_type and YQ.main_damage_type~=nGd[2468]and YQ.main_damage_type~=_Q then
return 0
end
local aR,bR=0,0
for cR,dR in pairs(XQ._core_damage_type_buffs or{})do
if ZQ[dR.damage_type]then
aR=aR+(tonumber(dR.mul)or 0)+(tonumber(dR.add_upg)or 0)*0.01+(tonumber(dR.pen)or 0)*0.001
bR=bR+(tonumber(dR.crit)or 0)
end
end
aR=aR+bR*0.5
local eR=V.rows(VQ.unit_id)
local fR=eR and eR[eR.max]
local gR=(fR and tonumber(fR.cd)or 0)*V.mult(VQ,nGd[1923])
for hR,iR in pairs(XQ._unique_relic_effects or{})do
local jR=type(iR.params)==nGd[1758]and iR.params or{}
if iR.id==nGd[2469]then
local kR=math.min(1,(tonumber(jR.extra_damage)or 0)*gR/math.max(1,tonumber(jR.time_interval)or 40))
local lR=V.DRONES and V.DRONES[VQ.unit_id]
if lR and lR.late and gR>0 then
local mR=1/gR
kR=kR*mR/(mR+(tonumber(lR.max)or 0)*(tonumber(lR.late.dmg)or 0)*(tonumber(lR.hits)or 1)/math.max(0.1,tonumber(lR.late.cd)or 4))
end
aR=aR+kR
elseif iR.id==nGd[2470]then
aR=aR+(tonumber(jR.dmg_buff)or 0)*0.25
elseif iR.id==nGd[2471]then
aR=aR+(tonumber(jR.dmg_buff)or 0)*bR
elseif iR.id==nGd[2472]then
if ZQ.magic then
aR=0
else
aR=aR+(tonumber(jR.dmg_buff)or 0)*0.3
end
elseif iR.id==nGd[2473]then
if ZQ.water_damage then
aR=aR+0.05
end
end
end
return aR
end
function jb.relicPlan()
local nR=N.session()
if not nR then
return nil
end
local oR=nR.inventory and nR.inventory.inventory_profile_data or{}
local pR={}
for qR,rR in ipairs(oR.unique_items or{})do
if type(rR)==nGd[1758]and rR.uuid and(N.Items[rR.item_id]or{}).item_group==nGd[2474]then
table.insert(pR,rR)
end
end
local sR={}
for tR,uR in ipairs(V.equipped())do
local vR=uR.data and uR.data.rarity
if not V.isFarm(uR.id)and(vR==nGd[2052]or vR==nGd[2053]or vR==nGd[2466]or vR==nGd[2475])then
local wR=jb.share(uR.id)
if not P.str.share[uR.id]then
wR=math.min(wR,0.15)
end
local xR={}
for yR,zR in ipairs(pR)do
local AR=jb.relicWorth(uR.u,zR)*wR*100
if AR>0.01 then
table.insert(xR,{it=zR,w=AR})
end
end
table.sort(xR,function(BR,CR)
if BR.w~=CR.w then
return BR.w>CR.w
end
return BR.it.uuid<CR.it.uuid
end)
local DR,ER={},{}
for FR,GR in ipairs(xR)do
local HR=ER[GR.it.item_id]or 0
if#DR<6 and HR<((N.Items[GR.it.item_id]or{}).unique_equip and 1 or 2)then
ER[GR.it.item_id]=HR+1
table.insert(DR,GR)
end
end
if uR.u._equipped_relic then
local IR=false
for JR,KR in ipairs(DR)do
if KR.it.uuid==uR.u._equipped_relic then
IR=true
end
end
local LR=not IR and nR.inventory:get_item_by_uuid(uR.u._equipped_relic)
if LR then
table.insert(DR,{it=LR,w=jb.relicWorth(uR.u,LR)*wR*100})
end
end
table.insert(sR,{e=uR,share=wR,opts=DR})
end
