local MR,NR={},-1
local OR,PR,QR={},{},{}
local function RR(SR,TR)
if SR> #sR then
if TR>NR then
NR=TR
MR=table.clone(OR)
end
return
end
local UR=sR[SR]
OR[UR.e.uuid]=nil
RR(SR+1,TR)
for VR,WR in ipairs(UR.opts)do
local XR=(N.Items[WR.it.item_id]or{}).unique_equip
if not PR[WR.it.uuid]and not(XR and QR[WR.it.item_id])then
PR[WR.it.uuid]=true
if XR then
QR[WR.it.item_id]=true
end
OR[UR.e.uuid]=WR.it.uuid
RR(SR+1,TR+WR.w+(WR.it.uuid==UR.e.u._equipped_relic and 0.01 or 0))
OR[UR.e.uuid]=nil
PR[WR.it.uuid]=nil
if XR then
QR[WR.it.item_id]=nil
end
end
end
end
RR(1,0)
local YR,ZR=0,{}
for _R,aS in ipairs(sR)do
local bS=aS.e.u._equipped_relic and nR.inventory:get_item_by_uuid(aS.e.u._equipped_relic)
local cS=bS and jb.relicWorth(aS.e.u,bS)*aS.share*100 or 0
YR=YR+cS
local dS=MR[aS.e.uuid]and nR.inventory:get_item_by_uuid(MR[aS.e.uuid])
local eS=dS and jb.relicWorth(aS.e.u,dS)*aS.share*100 or 0
table.insert(ZR,string.format(nGd[2476],V.name(aS.e.id),bS and(N.Items[bS.item_id]or{}).name or nGd[2063],cS,dS and(N.Items[dS.item_id]or{}).name or nGd[2063],eS))
end
return MR,NR-YR,ZR,sR
end
