function jb.xpGuess(PT)
local QT=PT.level and N.Levels[PT.level]
if not QT then
return 0
end
local RT=math.min(9,tonumber(QT.story_world_rank)or tonumber(PT.rank)or 9)
local TT=tonumber(QT.story_level_rank)or 6
local UT=(PT.kind==nGd[1797]and 1.5 or 1)*(RT>5 and 2 or 1)
local VT=2.1564^(RT-1)*(40+10*TT)/UT
if PT.kind==nGd[1777]then
VT=3*30*2.1564^(RT-1)/UT
end
local WT=RT>=9 and 0.3 or(RT>=7 and 0.5 or 1)
return VT*WT*6
end
