for rU,sU in ipairs(jb.foodHeld())do
local tU=sU.xp*mU
local uU=math.min(sU.n,math.floor((nU-pU)/math.max(1,tU)))
if uU>0 then
oU[sU.id]=uU
pU=pU+uU*tU
qU=qU+uU
end
