if not xU then
return
end
if vU.kind==nGd[2487]then
local yU=jb.feedPlan(xU)
local zU,AU,BU=yU.feed,yU.planned,yU.n
if BU==0 then
P.str.feedNote=vU.name..nGd[2494]
return
end
local CU,DU=tonumber(xU.xp)or 0,jb.level(xU)
local EU,FU=F.request(nGd[2487],nGd[2495],vU.uuid,zU)
local GU=U.now()
while U.now()-GU<4 and(tonumber((wU.collection:get_unit_by_uuid(vU.uuid)or xU).xp)or 0)<=CU do
task.wait(0.25)
end
local HU=wU.collection:get_unit_by_uuid(vU.uuid)or xU
local IU=(tonumber(HU.xp)or 0)-CU
if IU>0 then
local JU=jb.level(HU)
local KU=JU>DU and string.format(nGd[2489],DU,JU)or string.format(nGd[2490],DU)
cb.add(string.format(nGd[2496],BU,vU.name),BU,nGd[2497],string.format(nGd[2498],U.fmt(IU),KU))
jb.note(string.format(nGd[2499],vU.name,BU,U.fmt(IU),KU,math.abs(IU-AU)>AU*0.1 and string.format(nGd[2500],U.fmt(AU))or nGd[683]))
else
jb.note(string.format(nGd[2501],vU.name,tostring(EU and FU or nGd[2076])))
F.backoff(nGd[2487],600)
end
end
end
