function ib.shopAhead(TTb)
for UTb,VTb in ipairs(ib.rooms(TTb))do
if VTb.tags[ib.T.SHOP]then
return true
end
for WTb,XTb in ipairs(ib.after(TTb,VTb.choice))do
if XTb.tags[ib.T.SHOP]then
return true
end
end
end
return false
end
ib.LUCK_RESERVE=500
ib.MIN_WORTH=0.02
ib.TOP_WORTH=0.08
function ib.shop(YTb,ZTb)
