hUb.cost=math.ceil(hUb.cost*bUb)
table.insert(eUb,tostring(ib.item(hUb.id).name or hUb.id))
if not hUb.bought and not ib.isCurse(hUb.id)then
hUb.luck=tonumber(ib.item(hUb.id).luck_increase)~=nil
hUb.v=ib.itemValue(hUb.id,YTb)
if not hUb.luck and hUb.v/math.max(1,hUb.cost)<ib.MIN_WORTH then
fUb=fUb+1
elseif hUb.v>0 and(hUb.luck or _Tb>=10 or hUb.v/math.max(1,hUb.cost)>=ib.TOP_WORTH)then
table.insert(dUb,hUb)
end
end
end
table.sort(dUb,function(iUb,jUb)
if iUb.luck~=jUb.luck then
return iUb.luck
