return iUb.v/math.max(1,iUb.cost)>jUb.v/math.max(1,jUb.cost)
end)
local kUb,lUb,mUb={},0,0
for nUb,oUb in ipairs(dUb)do
if oUb.cost<=aUb-(oUb.luck and 0 or cUb)then
if ib.buy(oUb)then
aUb=ib.res(ib.data())
table.insert(kUb,string.format(nGd[3367],tostring(ib.item(oUb.id).name or oUb.id),oUb.cost))
end
elseif oUb.cost<=aUb then
mUb=mUb+1
else
lUb=lUb+1
