ib.note(string.format(nGd[3368],_Tb,#eUb>0 and table.concat(eUb,nGd[1869])or nGd[3369],#kUb>0 and(nGd[3370]..table.concat(kUb,nGd[1869]))or(_Tb<10 and nGd[3371]or(mUb>0 and nGd[3372]or nGd[3373])),aUb,lUb>0 and string.format(nGd[3374],lUb)or nGd[683],mUb>0 and string.format(nGd[3375],mUb,cUb)or nGd[683],fUb>0 and string.format(nGd[3376],fUb)or nGd[683]))
F.request(nGd[3377],nGd[3378])
end
function ib.shrine(pUb,qUb)
