function ib.wallet()
local CUb=N.session()and N.session().profile_data or{}
local DUb=CUb.inventory or{}
local EUb={gems=tonumber(N.cur(nGd[1821]))or 0,gold=tonumber(N.cur(nGd[1823]))or 0,items={},units={},unique=0}
