end
function ib.walletDiff(KUb,LUb)
local MUb={}
if LUb.gems~=KUb.gems then
table.insert(MUb,string.format(nGd[3385],LUb.gems-KUb.gems))
end
if LUb.gold~=KUb.gold then
table.insert(MUb,string.format(nGd[3386],LUb.gold-KUb.gold))
end
for NUb,OUb in pairs(LUb.items)do
if OUb~=(KUb.items[NUb]or 0)then
table.insert(MUb,string.format(nGd[3387],OUb-(KUb.items[NUb]or 0),tostring(NUb)))
end
end
for PUb,QUb in pairs(LUb.units)do
if not KUb.units[PUb]then
table.insert(MUb,nGd[3388]..V.name(QUb))
end
end
if LUb.unique~=KUb.unique then
table.insert(MUb,string.format(nGd[3389],LUb.unique-KUb.unique))
end
return#MUb>0 and table.concat(MUb,nGd[1869])or nGd[3390]
end
