local Xmc=_kc and not Vmc and bb.random and V.isFarm(Zkc.id)and bb.farmMergeOk()and{}or nil
local Ymc=bb.cands
local Zmc,_mc=Vmc or Tmc,Vmc and Wmc or Umc
if Zmc and _mc and _mc>0 then
