function bb.lookAt(Rnc)
local Snc,Tnc=math.huge,nil
for Unc,Vnc in ipairs(bb.samples)do
local Wnc=(U.flat(Vnc.pos)-U.flat(Rnc)).Magnitude
if Wnc<Snc then
Snc,Tnc=Wnc,Vnc.pos
end
end
local Xnc=Tnc and U.flat(Tnc-Rnc)or Vector3 .new(0,0,-1)
return Xnc.Magnitude>0.01 and Xnc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(Ync,Znc)
local _nc=V.isFarm(Ync.id)
local aoc,boc=bb.bestSpot(Ync,_nc or(bb.random and V.idol(Ync.id)),(bb.trainee~=nil and Ync.uuid==bb.trainee)or V.ENTRY[Ync.id]==true or(bb.studyEntry==true and Ync.id==bb.trialId))
if not aoc then
bb.noSpot[Ync.uuid]=(bb.noSpot[Ync.uuid]or 0)+1
F.status(nGd[3586],nGd[3675]..V.name(Ync.id))
return false
end
local coc=bb.money()
local doc,eoc=F.request(nGd[3676],nGd[3677],Ync.uuid,N.Util.CFramePLV(aoc,bb.lookAt(aoc)))
if doc and eoc then
bb.spent=bb.spent+(Ync.data.cost or 0)
table.insert(bb.actions,string.format(nGd[3678],V.name(Ync.id)))
F.log(1,nGd[3592],string.format(nGd[3679],V.name(Ync.id),bb.spotKey(aoc),boc,Znc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Ync.id,x=math.floor(aoc.X),z=math.floor(aoc.Z),cover=math.floor((boc or 0)+0.5),why=tostring(Znc):sub(1,90)})
F.status(nGd[3586],string.format(nGd[3680],V.name(Ync.id),Znc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[Ync.uuid]=(bb.placedAt[Ync.uuid]or 0)+1
return true
end
if coc>=(Ync.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[Ync.uuid]=(bb.placeFail[Ync.uuid]or 0)+1
if bb.placeFail[Ync.uuid]>=2 then
bb.noSpot[Ync.uuid]=3
F.log(1,nGd[3592],string.format(nGd[3681],V.name(Ync.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if doc and coc>=(Ync.data.cost or 0)and not bb.random then
local foc=bb.spotKey(aoc)
bb.refused[foc]=true
local goc=bb.mapKey()
P.blocked[goc]=P.blocked[goc]or{}
if not bb.refusedRun[foc]then
P.blocked[goc][foc]=(tonumber(P.blocked[goc][foc])or 0)+1
bb.refusedRun[foc]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[Ync.uuid]=(bb.unitRefusals[Ync.uuid]or 0)+1
if bb.unitRefusals[Ync.uuid]>=3 then
local hoc=math.max(1,bb.count(Ync.uuid))
if P.caps[Ync.uuid]~=hoc then
P.caps[Ync.uuid]=hoc
F.log(1,nGd[3592],string.format(nGd[3682],V.name(Ync.id),hoc))
end
end
F.log(2,nGd[3592],nGd[3683]..foc..nGd[2401]..V.name(Ync.id))
F.saveSoon()
end
return false
end
function bb.count(ioc)
