if loc then
for moc,noc in ipairs(loc:GetChildren())do
local ooc=noc:FindFirstChild(nGd[1820])
if ooc and ooc:FindFirstChild(nGd[3652])and ooc.player.Value==M and ooc.uuid.Value==ioc then
joc=joc+1
