function bb.measure()
local poc,qoc=bb.calRun,bb.info
if not(poc and qoc)then
return
end
pcall(bb.sampleHelpers)
local roc=U.now()
local soc=bb.wave()
local toc=bb.money()
if not poc.start and toc>0 and#bb.mine==0 then
poc.start=toc
end
if soc~=poc.lastW then
if bb.trialId and soc>0 then
bb.trialTrace=bb.trialTrace or{}
local uoc,voc,woc,xoc=0,{},0,0
for yoc,zoc in ipairs(bb.mine)do
local Aoc=zoc._stats
if Aoc.id.Value==bb.trialId then
uoc=uoc+1
table.insert(voc,tostring(Aoc.upgrade.Value))
elseif not V.isFarm(Aoc.id.Value)then
xoc=xoc+1
end
end
pcall(bb.sampleHelpers,true)
for Boc,Coc in pairs(bb.ownDealt)do
if Coc.id==bb.trialId then
woc=woc+Coc.v
end
end
local Doc=0
for Eoc,Foc in pairs(bb.helperDealt)do
if Foc.owner==bb.trialId then
Doc=Doc+Foc.v
end
end
table.insert(bb.trialTrace,string.format(nGd[3685],soc,roc-(bb.startT or roc),toc,table.concat(voc,nGd[2463]),xoc,woc+Doc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[soc-1]or 0,bb.teamDps or 0))
end
if poc.lastW and poc.lastW>0 and poc.lastWT then
table.insert(poc.waveSec,roc-poc.lastWT)
end
if poc.paidT and soc>0 and roc-poc.paidT<15 then
table.insert(poc.skip,roc-poc.paidT)
end
poc.paidT=nil
if soc>0 then
poc.alive[tostring(soc)]=bb.hpAliveRaw or 0
end
poc.lastW,poc.lastWT=soc,roc
end
local Goc=workspace:FindFirstChild(nGd[3686])
if Goc and soc>0 then
poc.timer[tostring(soc)]=math.max(poc.timer[tostring(soc)]or 0,tonumber(Goc.Value)or 0)
end
local Hoc=toc-(bb.lastMoneyR or toc)
bb.lastMoneyR=toc
bb.incomeLog=bb.incomeLog or{}
if Hoc>0 then
table.insert(bb.incomeLog,{t=roc,y=Hoc})
end
while bb.incomeLog[1]and roc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Ioc=0
for Joc,Koc in ipairs(bb.incomeLog)do
Ioc=Ioc+Koc.y
end
local Loc=math.min(30,roc-(bb.startT or roc))
bb.incomeRate=Loc>=8 and Ioc/Loc or nil
for Moc,Noc in ipairs(bb.enemies)do
local Ooc=Noc.m
local Poc=bb.track[Ooc]
if not Poc then
local Qoc=Ooc._stats
local Roc=Ooc:FindFirstChildOfClass(nGd[3511])
local Soc=qoc.cfgById[Qoc.id.Value]
local Toc=Soc and fb.baseStats(qoc,Soc)
if Roc and Toc and soc>0 then
local Uoc=Toc*qoc.hpRaw*fb.waveScale(qoc,soc,qoc.list[soc])
if Uoc>0 and Roc.MaxHealth>0 then
table.insert(poc.hp,Roc.MaxHealth/Uoc)
end
end
bb.track[Ooc]={t=roc,p=Noc.prog,sp=(Qoc:FindFirstChild(nGd[3687])and tonumber(Qoc.speed.Value))or 1}
if Roc and Roc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Roc.MaxHealth
end
if soc>0 then
poc.spawn[tostring(soc)]=(poc.spawn[tostring(soc)]or 0)+1
poc.spawnLast[tostring(soc)]=roc-(poc.lastWT or roc)
end
elseif not Poc.done and roc-Poc.t>=15 then
Poc.done=true
local Voc=(Noc.prog-Poc.p)/(roc-Poc.t)/math.max(0.1,Poc.sp)
if Voc>0.001 and Noc.prog<0.95 then
table.insert(poc.walk,Voc)
end
end
end
local Woc=0
for Xoc,Yoc in ipairs(bb.mine)do
local Zoc=Yoc._stats:FindFirstChild(nGd[3688])
if Zoc then
Woc=Woc+Zoc.Value
end
end
poc.potSum=poc.potSum or 0
if poc.lastDealtT then
local _oc=roc-poc.lastDealtT
local apc=0
poc.potBy=poc.potBy or{}
for bpc,cpc in ipairs(bb.mine)do
local dpc=cpc._stats
local epc=dpc.id.Value
if not V.isFarm(epc)and dpc:FindFirstChild(nGd[3689])and dpc.target.Value~=nil then
local fpc,gpc=pcall(bb.liveDps,cpc,epc)
if fpc and gpc then
apc=apc+gpc*_oc
local hpc=gpc/math.max(0.5,V.nudge(epc))
local ipc,jpc=pcall(function()
return V.passive(epc).mark
end)
if ipc and jpc and dpc:FindFirstChild(nGd[1922])then
hpc=hpc+(tonumber(jpc.dot)or 0)*dpc.damage.Value
end
poc.potBy[epc]=(poc.potBy[epc]or 0)+hpc*_oc
end
end
end
poc.potWin=(poc.potWin or 0)+apc
if roc-(poc.winT or roc)>=5 then
local kpc=Woc-(poc.winDealt or Woc)
if poc.potWin>0 and kpc>=0 then
poc.dealtSum=(poc.dealtSum or 0)+kpc
poc.potSum=poc.potSum+poc.potWin
end
poc.winT,poc.winDealt,poc.potWin=roc,Woc,0
end
end
if not poc.winT then
poc.winT,poc.winDealt=roc,Woc
end
poc.lastDealtT=roc
if soc~=poc.dpsW and soc>0 then
poc.dpsAt[tostring(soc)]=bb.teamDps or 0
poc.dpsW=soc
end
local lpc=math.min(1,roc-(poc.densT or roc))
poc.densT=roc
for mpc,npc in ipairs(bb.enemies)do
local opc=math.min(fb.BINS,math.floor(npc.prog*fb.BINS)+1)
poc.dens[opc]=(poc.dens[opc]or 0)+lpc
end
local ppc=workspace._BASES.player:FindFirstChild(nGd[3690])
local qpc=ppc and ppc:FindFirstChild(nGd[3691])
local rpc=qpc and qpc:FindFirstChildOfClass(nGd[3511])
if rpc then
poc.baseHp=math.max(poc.baseHp or 0,rpc.MaxHealth)
local spc=0
for tpc,upc in ipairs(bb.enemies)do
if upc.prog>=0.97 then
local vpc=upc.m:FindFirstChildOfClass(nGd[3511])
spc=spc+(vpc and vpc.MaxHealth or upc.hp)
end
end
if poc.lastBase and rpc.Health<poc.lastBase and spc>0 and poc.lastBaseT then
table.insert(poc.baseRel,(poc.lastBase-rpc.Health)/math.max(0.1,roc-poc.lastBaseT)/spc)
end
poc.lastBase,poc.lastBaseT=rpc.Health,roc
end
end
function bb.recordMap()
