Fpc[tostring(Ipc)]=table.concat(Opc)
if Hpc then
Gpc[tostring(Ipc)]={}
for Ypc,Zpc in pairs(Ppc)do
Gpc[tostring(Ipc)][Ypc]=table.concat(Zpc)
end
end
end
