function bb.baseVerdict(BHc,CHc)
local DHc=(CHc.t or 0)-(BHc.t or 0)
if DHc<bb.BASE_WIN-1 then
return false
end
local EHc=((tonumber(BHc.base)or 0)-(tonumber(CHc.base)or 0))/DHc
if EHc<=0 or(tonumber(CHc.base)or 0)<=0 then
return false
end
local FHc=CHc.base/EHc
local GHc,HHc=0,0
local IHc,JHc=BHc.foes or{},CHc.foes or{}
for KHc,LHc in pairs(JHc)do
if LHc.prog>=bb.BASE_END then
GHc=GHc+LHc.hp
local MHc=IHc[KHc]
if MHc then
HHc=HHc+math.max(0,MHc.hp-LHc.hp)
end
end
end
for NHc,OHc in pairs(IHc)do
if OHc.prog>=bb.BASE_END and not JHc[NHc]then
HHc=HHc+OHc.hp
end
end
if GHc<=0 then
return false
end
local PHc=HHc/DHc
local QHc=PHc>0 and GHc/PHc or math.huge
local RHc={baseTime=FHc,loss=EHc,atEnd=GHc,rate=PHc,killTime=QHc}
return FHc<bb.BASE_SOON and QHc>FHc*bb.BASE_MARGIN,RHc
end
